function indentationEdits(source,formatted){
  // Copy only leading whitespace from the language formatter. Preserve every
  // original line and all code, including quotes, spacing and line endings.
  if(source.replace(/\s/g,'')!==formatted.replace(/\s/g,''))return [];
  const indents=new Map();
  let offset=0;
  for(const line of formatted.split(/\r\n|\r|\n/)){
    const content=line.replace(/\s/g,'');
    if(content)indents.set(offset,/^[\t ]*/.exec(line)[0]);
    offset+=content.length;
  }
  offset=0;
  const edits=[];
  source.split(/\r\n|\r|\n/).forEach((line,index)=>{
    const content=line.replace(/\s/g,'');
    const before=/^[\t ]*/.exec(line)[0];
    const after=indents.get(offset);
    if(content&&after!==undefined&&before!==after)edits.push({
      range:{startLineNumber:index+1,startColumn:1,endLineNumber:index+1,endColumn:before.length+1},text:after
    });
    offset+=content.length;
  });
  return edits;
}
