function renderPreferences(){const root=$('#preferences');root.innerHTML=`<div class="preferences-layout"><div class="preferences-title"><div><div class="eyebrow">MAKE YOURSELF AT HOME</div><h1>Preferences</h1><p>Your editor. Your rhythm. Your rules.</p></div><button class="secondary-button" id="reset-preferences">Reset to defaults</button></div><input class="preferences-search" id="preferences-search" placeholder="Search settings…" aria-label="Search settings" value="${escapeHtml(prefFilter)}"><div class="preferences-nav">${['appearance','editor','workspace','shortcuts'].map(t=>`<button class="${prefTab===t?'active':''}" data-pref-tab="${t}">${({appearance:'Appearance',editor:'Editor',workspace:'Workspace',shortcuts:'Keyboard shortcuts'})[t]}</button>`).join('')}</div><div id="settings-content"></div><div class="preferences-bottom"><button class="secondary-button" data-action="updates">Updates</button> <span>BlueGay 1.0.5</span></div><div class="preferences-bottom" id="settings-storage-status">${escapeHtml(settingsStorageMessage())}</div></div>`;$('#preferences-search').oninput=e=>{prefFilter=e.target.value;renderSettingsContent();};$('#reset-preferences').onclick=()=>confirmAction('Reset preferences?','Restore all appearance, editor, and workspace preferences to their defaults. Your files will be kept.',()=>{prefs={...defaults};savePreferences();renderPreferences();toast('Preferences reset.');},'Reset preferences');renderSettingsContent();}
function renderSettingsContent(){const q=prefFilter.toLowerCase();const root=$('#settings-content');if(prefTab==='shortcuts'){const rows=shortcutRows.filter(r=>r.join(' ').toLowerCase().includes(q));root.innerHTML=`<section class="settings-section"><h2>A shortcut to your flow</h2><p>On macOS, use ⌘ in place of Ctrl for editor shortcuts. Language services vary by language.</p><table class="shortcut-table"><tbody>${rows.map(([label,key])=>`<tr><td>${label}</td><td><kbd>${key}</kbd></td></tr>`).join('')}</tbody></table></section>`;return;}let html='';if(prefTab==='appearance')html=renderThemePreferences(q);
const groups=q?Object.values(settingGroups).flat():settingGroups[prefTab];for(const [title,description,settings]of groups){const filtered=settings.filter(([id,label,desc])=>(label+' '+desc+' '+(window.BlueGayI18n?.translate(label)||'')+' '+(window.BlueGayI18n?.translate(desc)||'')).toLowerCase().includes(q));if(!filtered.length)continue;html+=`<section class="settings-section"><h2>${title}</h2><p>${description}</p>${filtered.map(([id,label,desc,type,min,max])=>{let control;if(type==='toggle')control=`<button class="toggle ${prefs[id]?'on':''}" role="switch" aria-checked="${prefs[id]}" aria-label="${label}" data-toggle="${id}"></button>`;else if(type==='predictionModel')control=`<select data-setting="${id}" aria-label="${label}">${predictionModelOptions()}</select>`;else if(type==='number')control=`<input type="number" min="${min}" max="${max}" value="${prefs[id]}" data-setting="${id}" aria-label="${label}">`;else control=`<select data-setting="${id}" aria-label="${label}">${type.map(v=>`<option ${String(prefs[id])===v?'selected':''} value="${v}">${id==='locale'?({en:'English','fr-CA':'Français (Canada)'})[v]:v}</option>`).join('')}</select>`;return `<div class="setting-row"><div><h3>${label}</h3><p>${desc}</p></div>${control}</div>`;}).join('')}</section>`;}
if((prefTab==='editor'||q)&&prefs.codePrediction)html+=`<p class="info-note" id="prediction-status" role="status">${escapeHtml(codePredictions?.status()||'Code prediction uses the connection selected in ChatLGBT. Connect an account to start. Suggestions use model allowance even when dismissed.')}</p>`;if(prefTab==='workspace'&&!q)html+=disk.available?'<div class="info-note">Ctrl+S saves directly to the opened disk file. Autosave applies to files with a disk location. Unsaved text and recent file history are also kept in local recovery storage. External changes are checked every four seconds and when the window regains focus.</div>':'<div class="info-note">Browser preview: files stay in browser storage. The desktop app saves directly to disk.</div>';root.innerHTML=html||'<div class="setting-empty">No settings found. Try a different search.</div>';$('#custom-accent')?.addEventListener('input',e=>{prefs.accent=e.target.value;savePreferences();$('#settings-content').querySelectorAll('[data-accent]').forEach(button=>{const selected=button.dataset.accent===prefs.accent;button.classList.toggle('selected',selected);button.setAttribute('aria-pressed',String(selected));});});}

function registerSnippets(){const data={python:[['def','Function definition','def ${1:function_name}(${2:args}):\n\t${0:pass}'],['class','Class definition','class ${1:ClassName}:\n\tdef __init__(self${2:}):\n\t\t${0:pass}'],['for','For loop','for ${1:item} in ${2:items}:\n\t${0:pass}'],['if','If statement','if ${1:condition}:\n\t${0:pass}'],['try','Try / except','try:\n\t${1:pass}\nexcept ${2:Exception} as ${3:error}:\n\t${0:pass}'],['print','Print value','print(${1:value})'],['import','Import module','import ${1:module}']],rust:[['fn','Function','fn ${1:name}(${2:}) ${3:-> ()} {\n\t${0}\n}'],['struct','Struct','struct ${1:Name} {\n\t${2:field}: ${3:String},\n}'],['impl','Implementation','impl ${1:Name} {\n\t${0}\n}'],['println','Print line','println!("${1:message}");']],go:[['func','Function','func ${1:name}(${2:}) ${3:} {\n\t${0}\n}'],['if','If statement','if ${1:condition} {\n\t${0}\n}'],['for','Range loop','for ${1:key}, ${2:value} := range ${3:items} {\n\t${0}\n}']],java:[['class','Class','public class ${1:Name} {\n\t${0}\n}'],['main','Main method','public static void main(String[] args) {\n\t${0}\n}'],['sout','Print line','System.out.println(${1:value});']],cpp:[['for','For loop','for (int ${1:i} = 0; ${1:i} < ${2:count}; ${1:i}++) {\n\t${0}\n}'],['class','Class','class ${1:Name} {\npublic:\n\t${0}\n};']],c:[['for','For loop','for (int ${1:i} = 0; ${1:i} < ${2:count}; ${1:i}++) {\n\t${0}\n}'],['printf','Print formatted','printf("${1:%s}\\n", ${2:value});']],csharp:[['class','Class','public class ${1:Name}\n{\n\t${0}\n}'],['prop','Property','public ${1:string} ${2:Name} { get; set; }']],ruby:[['def','Method','def ${1:name}(${2:})\n\t${0}\nend'],['class','Class','class ${1:Name}\n\t${0}\nend']],php:[['function','Function','function ${1:name}(${2:}) {\n\t${0}\n}']],sql:[['select','SELECT query','SELECT ${1:*}\nFROM ${2:table}\nWHERE ${3:condition};'],['insert','INSERT query','INSERT INTO ${1:table} (${2:columns})\nVALUES (${3:values});'],['join','Join table','JOIN ${1:table} ON ${2:condition}']],shell:[['if','If statement','if ${1:condition}; then\n\t${0}\nfi'],['for','For loop','for ${1:item} in ${2:items}; do\n\t${0}\ndone']],markdown:[['link','Link','[${1:text}](${2:url})'],['code','Code block','```${1:language}\n${2:code}\n```']]};for(const [language,snippets]of Object.entries(data)){monaco.languages.registerCompletionItemProvider(language,{provideCompletionItems(model,position){const word=model.getWordUntilPosition(position);return {suggestions:snippets.map(([label,detail,insertText])=>({label,detail,insertText,kind:monaco.languages.CompletionItemKind.Snippet,insertTextRules:monaco.languages.CompletionItemInsertTextRule.InsertAsSnippet,range:{startLineNumber:position.lineNumber,endLineNumber:position.lineNumber,startColumn:word.startColumn,endColumn:word.endColumn}}))};}});}}

document.addEventListener('click',e=>{const action=e.target.closest('[data-action]');if(action){e.preventDefault();runAction(action.dataset.action);return;}const close=e.target.closest('[data-close]');if(close){closeTab(close.dataset.close);return;}const tab=e.target.closest('[data-tab]');if(tab){switchTab(tab.dataset.tab);return;}const file=e.target.closest('[data-file]');if(file){const id=file.dataset.file;switchTab(id);if(sidebarView==='explorer')$('#sidebar-content [data-file="'+id+'"]')?.focus();if(innerWidth<780)$('#sidebar').classList.add('hidden-mobile');return;}const folder=e.target.closest('[data-folder]');if(folder){const path=folder.dataset.folder;collapsed.has(path)?collapsed.delete(path):collapsed.add(path);renderTree();$('#sidebar-content [data-folder]').find(row=>row.dataset.folder===path)?.focus();return;}const view=e.target.closest('[data-view]');if(view){if(view.dataset.view===sidebarView&&!$('#sidebar').hidden){$('#sidebar').hidden=true;renderSidebar();}else setSidebar(view.dataset.view);return;}const menu=e.target.closest('[data-top-menu]');if(menu){const r=menu.getBoundingClientRect();showPopup(menuItems(menu.dataset.topMenu),r.left,r.bottom+7);return;}const panel=e.target.closest('[data-panel]');if(panel){panelView=panel.dataset.panel;renderPanel();return;}const theme=e.target.closest('[data-theme]');if(theme){prefs.theme=theme.dataset.theme;savePreferences();renderSettingsContent();return;}const accent=e.target.closest('[data-accent]');if(accent){prefs.accent=accent.dataset.accent;savePreferences();renderSettingsContent();return;}const toggle=e.target.closest('[data-toggle]');if(toggle){prefs[toggle.dataset.toggle]=!prefs[toggle.dataset.toggle];savePreferences();renderSettingsContent();return;}const pref=e.target.closest('[data-pref-tab]');if(pref){prefTab=pref.dataset.prefTab;renderPreferences();return;}const result=e.target.closest('[data-search-file]');if(result){switchTab(result.dataset.searchFile);editor?.setPosition({lineNumber:+result.dataset.line,column:1});editor?.revealLineInCenter(+result.dataset.line);editor?.focus();return;}const diff=e.target.closest('[data-diff]');if(diff){showDiff(files.find(f=>f.id===diff.dataset.diff));return;}const revert=e.target.closest('[data-revert]');if(revert){const f=files.find(f=>f.id===revert.dataset.revert);confirmAction('Revert file?',`Restore ${f.path} to the last checkpoint?`,()=>{const m=modelFor(f);m.pushEditOperations([],[{range:m.getFullModelRange(),text:f.baseline}],()=>null);renderChanges();},'Revert file');return;}const restore=e.target.closest('[data-restore]');if(restore){const f=currentFile(),text=f.history[+restore.dataset.restore].content;confirmAction('Restore snapshot?','Replace the current contents with this saved snapshot? The current version will remain in history.',()=>{f.history.unshift({at:Date.now(),content:f.content});f.history=f.history.slice(0,20);const m=modelFor(f);m.pushEditOperations([],[{range:m.getFullModelRange(),text}],()=>null);saveFile(f);renderPanel();},'Restore snapshot');return;}if(!e.target.closest('#popup'))$('#popup').hidden=true;});
document.addEventListener('change',e=>{const el=e.target;if(el.matches('[data-setting]')){let value=el.value;if(['tabSize','fontSize','lineHeight'].includes(el.dataset.setting)){value=Number(value);if(el.type==='number')value=Math.max(+el.min,Math.min(+el.max,value||+el.min));el.value=value;}prefs[el.dataset.setting]=value;savePreferences();}});
document.addEventListener('contextmenu',e=>{const problem=e.target.closest('[data-problem]');if(problem){e.preventDefault();const m=workspaceMarkers().filter(m=>m.severity>=4)[+problem.dataset.problem];if(m)showPopup([{label:'Explain this error with ChatLGBT',run:()=>explainError({file:files.find(f=>modelForSafe(f)?.uri.toString()===m.resource.toString()),line:m.startLineNumber,message:m.message})}],e.clientX,e.clientY);return;}if(e.target.closest('.project-header')){e.preventDefault();showPopup([{label:'New file…',run:()=>newFileInFolder('')},'-',{label:'Close Project',run:()=>closeProject()}],e.clientX,e.clientY);return;}const folder=e.target.closest('#sidebar-content [data-folder]');if(folder){e.preventDefault();folder.focus();showPopup([{label:'New file…',run:()=>newFileInFolder(folder.dataset.folder)},'-',{label:'Delete folder',key:'Del',danger:true,run:()=>deleteFolder(folder.dataset.folder)}],e.clientX,e.clientY);return;}const row=e.target.closest('[data-file]');if(row){e.preventDefault();row.focus();const f=files.find(f=>f.id===row.dataset.file);if(!f)return;showPopup([{label:'Open file',run:()=>switchTab(f.id)},...(window.BlueGayPreviewCore?.kind(f.path)?[{label:'Preview file',run:()=>window.BlueGayPreviews.open(f)}]:[]),...(/\.html?$/i.test(f.path)?[{label:'Open HTML in browser',key:'Ctrl Alt B',run:()=>openHtmlInBrowser(f)}]:[]),{label:'Rename…',key:'F2',run:()=>renameFile(f)},...(!f.unsupported?[{label:'Download file',run:()=>downloadBlob(new Blob([f.content]),fileName(f.path))},{label:'Compare with checkpoint',run:()=>showDiff(f)}]:[]),'-',{label:'Delete file',key:'Del',danger:true,run:()=>deleteFile(f)}],e.clientX,e.clientY);}});
$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=$('#modal').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeModal();}});$('#modal').addEventListener('cancel',e=>{e.preventDefault();closeModal();});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){document.body.classList.remove('zen');$('#popup').hidden=true;}if($('#modal').open)return;const mod=e.ctrlKey||e.metaKey,key=e.key.toLowerCase();let action;if(key==='delete'&&!mod&&!e.altKey&&!e.shiftKey&&sidebarView==='explorer'){const row=e.target.closest('#sidebar-content [data-file], #sidebar-content [data-folder]');if(row){e.preventDefault();e.stopPropagation();$('#popup').hidden=true;if(row.dataset.folder)deleteFolder(row.dataset.folder);else{const file=files.find(f=>f.id===row.dataset.file);if(file)deleteFile(file);}return;}}if(key==='f2'&&!mod&&!e.altKey&&!e.shiftKey){const row=e.target.closest('#sidebar-content [data-file]');const f=row&&files.find(f=>f.id===row.dataset.file);if(f&&sidebarView==='explorer'){e.preventDefault();e.stopPropagation();$('#popup').hidden=true;renameFile(f);return;}}if(e.altKey&&!mod&&key==='z'){e.preventDefault();runAction('wordWrap');return;}if(mod&&e.altKey&&key==='s'){e.preventDefault();runAction('saveAll');return;}if(mod&&e.altKey&&['arrowright','arrowleft'].includes(key)){e.preventDefault();const i=tabs.indexOf(activeId);switchTab(tabs[(i+(key==='arrowright'?1:-1)+tabs.length)%tabs.length]);return;}if(mod&&!e.altKey){if(e.shiftKey){action=({s:'saveAs',f:'search',e:'explorer'})[key];}else{action=({s:'save',o:'openFolder',n:'newFile',k:'palette',p:'quickOpen',',':'preferences',b:'toggleSidebar',j:'togglePanel','\\':'split',w:'closeTab','=':'zoomIn','+':'zoomIn','-':'zoomOut'})[key];}}if(action){e.preventDefault();e.stopPropagation();if(action==='closeTab')closeTab(activeId);else if(action==='explorer')setSidebar('explorer');else runAction(action);}},true);
$('#file-input').onchange=async e=>{await importBrowserFiles([...e.target.files]);e.target.value='';};$('#folder-input').onchange=async e=>{await importBrowserFiles([...e.target.files],true);e.target.value='';};$('#zip-input').onchange=async e=>{await importZip(e.target.files[0]);e.target.value='';};
let dragDepth=0;document.addEventListener('dragenter',e=>{if(!e.dataTransfer.types.includes('Files'))return;e.preventDefault();dragDepth++;if(!$('.drop-overlay')){const d=document.createElement('div');d.className='drop-overlay';d.textContent='Drop files to open in BlueGay';document.body.append(d);}});document.addEventListener('dragover',e=>{if(e.dataTransfer.types.includes('Files'))e.preventDefault();});document.addEventListener('dragleave',()=>{if(--dragDepth<=0){dragDepth=0;$('.drop-overlay')?.remove();}});document.addEventListener('drop',async e=>{e.preventDefault();dragDepth=0;$('.drop-overlay')?.remove();if(disk.available)return;const list=[...e.dataTransfer.files];if(list.length===1&&list[0].name.endsWith('.zip'))await importZip(list[0]);else await importBrowserFiles(list);});
window.addEventListener('beforeunload',e=>{persist();if(disk.available)return;if(dirtyStorage||files.some(f=>f.content!==f.saved)&&!prefs.autoSave){e.preventDefault();e.returnValue='';}});
applyPreferences();renderTabs();renderSidebar();renderPanel();if(innerWidth<780)$('#sidebar').classList.add('hidden-mobile');
require.config({paths:{vs:new URL('vendor/vs',location.href).href}});
require(['vs/editor/editor.main'],()=>{monacoReady=true;if(!monaco.languages.getLanguages().some(l=>l.id==='toml'))monaco.languages.register({id:'toml',extensions:['.toml'],aliases:['TOML']});localDiagnostics=window.BlueGayDiagnostics.install(monaco,()=>{if(monacoReady)updateProblems();});javascriptIntelligence=window.BlueGayJavaScript.install(monaco);const htmlDefaults=monaco.languages.html.htmlDefaults;htmlDefaults.setOptions({...htmlDefaults.options,format:{...htmlDefaults.options.format,indentInnerHtml:true}});registerSnippets();BlueGayHtml.register(monaco,()=>({paths:[...files.map(f=>f.path),...explicitFolders.map(p=>p+'/')]}));$('#editor').innerHTML='';editor=monaco.editor.create($('#editor'),{...editorOptions(),model:null});installCodePredictions();installErrorHelp(editor);window.BlueGayPreviews?.installUI();editor.onDidChangeCursorPosition(()=>updateStatus());monaco.editor.onDidChangeMarkers(updateProblems);files.forEach(f=>modelFor(f));applyPreferences();switchTab(activeId);updateProblems();window.BlueGay={get files(){return files;},get editor(){return editor;},get prefs(){return prefs;},get predictions(){return codePredictions;},get javascript(){return javascriptIntelligence;},languageFor,runAction,saveFile,exportZip};window.dispatchEvent(new Event('bluegay-ready'));},error=>{$('#editor').innerHTML='<div class="editor-error">The editor could not load. Please refresh the page. Your saved files are still in browser storage.</div>';console.error(error);});
